import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(page_title="ISSF Trap Preview", page_icon="🎯", layout="centered")

html = r"""
<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><style>
html,body{margin:0;background:#0f1720;color:#fff;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.app{max-width:520px;margin:auto;padding:10px}.head{display:flex;justify-content:space-between;align-items:center}.sub{font-size:12px;color:#aab7c4;margin-bottom:8px}button{background:#24323c;color:#fff;border:1px solid #394955;border-radius:10px;padding:9px 7px;font-weight:800}.active{background:#ff681c;border-color:#ff984f}.stage{position:relative;border-radius:18px;overflow:hidden;border:1px solid #33444f;touch-action:manipulation;background:#72b9e5}canvas{display:block;width:100%;height:54vh;touch-action:manipulation}.tap{position:absolute;inset:0;display:grid;place-items:center;pointer-events:none}.pill{background:#0008;padding:11px 16px;border-radius:999px;font-weight:900}.info{position:absolute;left:10px;bottom:10px;background:#051014cc;padding:8px 10px;border-radius:10px;font-size:12px}.panel{background:#18242d;border:1px solid #263740;border-radius:14px;padding:10px;margin-top:8px}.row{display:flex;justify-content:space-between;font-size:13px;color:#c7d2da}.grid10{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;margin-top:7px}.grid5{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;margin-top:7px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-top:7px}.card{background:#24323c;border:1px solid #394955;border-radius:10px;padding:8px 4px;text-align:center;font-size:12px;line-height:1.5}.next{margin-top:8px;background:#101b22;padding:9px;border-radius:10px;text-align:center;font-weight:800;font-size:13px}.note{font-size:11px;color:#9cacb8;line-height:1.55}.hidden{display:none}
</style></head><body><div class="app">
<div class="head"><div><b style="font-size:20px">ISSF Trap Preview</b><div class="sub">2026セット表 Ver.3 ・ 試合前確認</div></div><button id="infoBtn">情報 ON</button></div>
<div class="stage" id="stage"><canvas id="cv"></canvas><div class="tap" id="tap"><span class="pill">タップで即放出</span></div><div class="info hidden" id="info"></div></div>
<div class="panel"><div class="row"><b>セット</b><span id="setLabel">1番</span></div><div class="grid10" id="sets"></div></div>
<div class="panel"><div class="row"><b>射台</b><span id="stationLabel">1番射台</span></div><div class="grid5" id="stations"></div></div>
<div class="panel"><div class="row"><b>3方向の確認順</b><span>番号順に循環</span></div><div class="grid3" id="cards"></div><div class="next" id="next"></div></div>
<p class="note">画面をタップすると即放出。同一射台の3本を放出機番号順に繰り返します。距離は76m固定。高度は放出口から10m地点の値です。</p>
</div><script>
const SETS={
1:[[30,2.50],[10,1.50],[-30,3.00],[40,1.70],[-5,2.00],[-45,2.00],[45,2.00],[-10,3.00],[-45,2.80],[45,2.30],[10,1.80],[-40,1.60],[30,2.00],[-5,1.50],[-35,3.00]],
2:[[45,2.30],[10,1.50],[-20,2.80],[45,1.50],[0,2.00],[-45,2.00],[25,2.00],[0,3.00],[-45,1.50],[35,2.20],[10,2.40],[-40,1.50],[30,2.80],[-10,1.50],[-45,2.00]],
3:[[45,2.50],[0,1.60],[-20,2.00],[35,2.90],[-5,1.80],[-45,3.00],[35,2.50],[-10,3.00],[-40,2.20],[40,2.00],[-5,2.50],[-30,3.00],[30,2.00],[0,1.80],[-30,3.00]],
4:[[30,1.50],[0,3.00],[-20,2.20],[30,2.00],[-10,1.50],[-45,3.00],[25,3.00],[-5,1.50],[-15,1.80],[40,2.80],[-5,1.50],[-35,2.20],[15,3.00],[10,3.00],[-40,1.70]],
5:[[20,1.80],[0,3.00],[-25,2.60],[35,3.00],[0,1.60],[-35,3.00],[35,2.30],[-5,1.80],[-35,1.60],[40,2.30],[0,2.30],[-40,3.00],[25,1.80],[-5,2.50],[-45,2.00]],
6:[[45,1.90],[0,2.80],[-30,3.00],[40,1.50],[0,1.60],[-40,2.00],[35,2.00],[0,3.00],[-45,2.00],[45,2.30],[5,2.00],[-40,3.00],[25,2.40],[0,1.75],[-35,1.80]],
7:[[40,3.00],[0,1.50],[-35,1.50],[45,2.00],[5,2.20],[-45,3.00],[40,1.50],[5,1.90],[-25,2.60],[20,1.80],[0,3.00],[-30,2.20],[35,2.50],[0,3.00],[-40,3.00]],
8:[[40,3.00],[-5,3.00],[-15,2.20],[30,2.00],[-5,2.00],[-35,1.80],[40,2.00],[5,1.50],[-35,2.50],[45,1.50],[5,2.00],[-25,3.00],[15,1.50],[0,1.50],[-45,1.60]],
9:[[30,1.60],[0,1.50],[-15,2.00],[20,2.40],[-5,3.00],[-35,2.00],[45,2.00],[-5,1.50],[-35,1.50],[45,1.60],[0,2.80],[-45,2.00],[25,3.00],[5,1.50],[-20,3.00]],
10:[[45,2.25],[0,1.75],[-25,2.00],[35,1.80],[0,3.00],[-40,2.25],[40,3.00],[5,1.80],[-45,3.00],[45,2.00],[-10,2.50],[-35,1.50],[15,1.80],[10,2.00],[-45,1.50]]};
let setNo=1,station=1,shot=0,flying=false,showInfo=true,raf=null; const cv=document.getElementById('cv'),ctx=cv.getContext('2d');
const angleText=a=>a>0?`右${a}°`:a<0?`左${Math.abs(a)}°`:'直進';
function resize(){const r=cv.getBoundingClientRect(),d=devicePixelRatio||1;cv.width=Math.round(r.width*d);cv.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);drawIdle()}
function bg(){const w=cv.clientWidth,h=cv.clientHeight,hz=h*.48,sky=ctx.createLinearGradient(0,0,0,hz);sky.addColorStop(0,'#72b9e5');sky.addColorStop(1,'#d9eff9');ctx.fillStyle=sky;ctx.fillRect(0,0,w,hz);const g=ctx.createLinearGradient(0,hz,0,h);g.addColorStop(0,'#7da251');g.addColorStop(1,'#345a2c');ctx.fillStyle=g;ctx.fillRect(0,hz,w,h-hz);const hw=w*.52,hh=h*.065,hx=(w-hw)/2,hy=h*.64;ctx.fillStyle='#3d4d56';ctx.fillRect(hx,hy,hw,hh);ctx.fillStyle='#1f2b31';ctx.fillRect(hx,hy-12,hw,12);ctx.strokeStyle='#ffffffaa';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(w/2,hy-12);ctx.lineTo(w/2,h);ctx.stroke()}
function drawIdle(){if(flying)return;bg();const w=cv.clientWidth,base=(station-1)*3+1;ctx.fillStyle='#0007';ctx.fillRect(0,0,w,42);ctx.fillStyle='white';ctx.font='600 14px system-ui';ctx.textAlign='center';ctx.fillText(`${setNo}番セット・${station}番射台・次は放出機${base+shot}`,w/2,27)}
function renderUI(){document.getElementById('setLabel').textContent=setNo+'番';document.getElementById('stationLabel').textContent=station+'番射台';document.querySelectorAll('#sets button').forEach((b,i)=>b.className=(i+1===setNo?'active':''));document.querySelectorAll('#stations button').forEach((b,i)=>b.className=(i+1===station?'active':''));const pool=SETS[setNo].slice((station-1)*3,station*3),base=(station-1)*3+1,c=document.getElementById('cards');c.innerHTML='';pool.forEach(([a,h],i)=>{const d=document.createElement('div');d.className='card '+(i===shot?'active':'');d.innerHTML=`<b>放出機 ${base+i}</b><br>${angleText(a)}<br><small>高度 ${h.toFixed(2)}m</small>`;c.appendChild(d)});const [a,h]=pool[shot];document.getElementById('next').textContent=`次：放出機 ${base+shot}・${angleText(a)}・高度 ${h.toFixed(2)}m`;drawIdle()}
function launch(){if(flying)return;flying=true;document.getElementById('tap').classList.add('hidden');const pool=SETS[setNo].slice((station-1)*3,station*3),current=shot,[angle,height]=pool[current],base=(station-1)*3+1;const inf=document.getElementById('info');inf.textContent=`放出機 ${base+current}　${angleText(angle)}　高度 ${height.toFixed(2)}m　距離 76m`;if(showInfo)inf.classList.remove('hidden');const w=cv.clientWidth,h=cv.clientHeight,start=performance.now(),dur=2200,sx=w/2,sy=h*.64-12,dir=angle/45,ex=w/2+dir*w*.44,hn=(height-1.5)/1.5,ey=h*.35-hn*h*.32;function frame(now){const t=Math.min(1,(now-start)/dur),travel=1-Math.pow(1-t,1.15);bg();const px=sx+(ex-sx)*travel,py=sy+(ey-sy)*travel-(28+42*hn)*Math.sin(Math.PI*t),scale=Math.max(.22,1-.72*t);ctx.save();ctx.translate(px,py);/* horizontal clay: no rotation */ctx.scale(scale,scale*.34);ctx.fillStyle='#ff5b18';ctx.beginPath();ctx.arc(0,0,14,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffe0bd';ctx.lineWidth=2;ctx.stroke();ctx.restore();if(t<1)raf=requestAnimationFrame(frame);else{shot=(current+1)%3;flying=false;document.getElementById('tap').classList.remove('hidden');renderUI()}}raf=requestAnimationFrame(frame)}
for(let i=1;i<=10;i++){const b=document.createElement('button');b.textContent=i;b.onclick=e=>{e.stopPropagation();setNo=i;shot=0;renderUI()};document.getElementById('sets').appendChild(b)}for(let i=1;i<=5;i++){const b=document.createElement('button');b.textContent=i+'番';b.onclick=e=>{e.stopPropagation();station=i;shot=0;renderUI()};document.getElementById('stations').appendChild(b)}document.getElementById('stage').addEventListener('pointerdown',e=>{e.preventDefault();launch()});document.getElementById('infoBtn').onclick=()=>{showInfo=!showInfo;document.getElementById('infoBtn').textContent='情報 '+(showInfo?'ON':'OFF');if(!showInfo)document.getElementById('info').classList.add('hidden')};window.addEventListener('resize',resize);requestAnimationFrame(()=>{resize();renderUI()});
</script></body></html>
"""
components.html(html, height=920, scrolling=True)
